export const CAPTURED_DOCUMENT_ENVELOPE = Object.freeze(
  ENVELOPE.map((entry) =>
    Object.freeze({ ...entry, document: JSON.parse(entry.json) }),
  ),
);

/* An embedded Agent is a whole document, and these are the questions the pool
 * validator asks of it through `prepare_agent_graph`. The first of them is
 * the one acceptance 6 is about: a complete, legal, pure Workflow is a
 * perfectly good document and a Subagent Pool may not hold it. The envelope
 * cannot say so — a Workflow is only refused there for holding an Agent node
 * — so the kind has to be asked separately, which is exactly what the runtime
 * does and what this mirror missed. */

